-- cupel-evidence: generated by `python -m tools.d1_tables schema`; change Supabase, not this.

CREATE TABLE IF NOT EXISTS "bulk_block_deals" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "kind" TEXT NOT NULL,
    "deal_date" TEXT NOT NULL,
    "symbol" TEXT NOT NULL,
    "client_name" TEXT NOT NULL,
    "side" TEXT NOT NULL,
    "quantity" INTEGER NOT NULL,
    "price" REAL NOT NULL,
    "remarks" TEXT,
    PRIMARY KEY ("market", "kind", "deal_date", "symbol", "client_name", "side", "quantity", "price")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "company_documents" (
    "market" TEXT NOT NULL,
    "symbol" TEXT NOT NULL,
    "kind" TEXT NOT NULL,
    "announced_at" TEXT NOT NULL,
    "title" TEXT NOT NULL,
    "url" TEXT NOT NULL,
    "period" TEXT,
    PRIMARY KEY ("market", "symbol", "kind", "url")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "estimate_history" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "symbol" TEXT NOT NULL,
    "fetched_at" TEXT NOT NULL,
    "observed_on" TEXT NOT NULL,
    "forward_eps" REAL,
    "forward_pe" REAL,
    "trailing_eps" REAL,
    "analyst_count" INTEGER,
    "target_mean_price" REAL,
    "recommendation_mean" REAL,
    "price" REAL,
    "updated_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("market", "symbol", "fetched_at")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "red_flag_snapshots" (
    "source" TEXT NOT NULL,
    "symbol" TEXT NOT NULL,
    "severity" INTEGER NOT NULL DEFAULT 0,
    "flag_count" INTEGER NOT NULL DEFAULT 0,
    "summary" TEXT NOT NULL,
    "source_status" TEXT NOT NULL,
    "source_as_of" TEXT NOT NULL,
    "snapshot" TEXT NOT NULL,
    "fetched_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("source", "symbol")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "shareholding_patterns" (
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "symbol" TEXT NOT NULL,
    "period_end" TEXT NOT NULL,
    "record_id" TEXT NOT NULL,
    "filed_at" TEXT NOT NULL,
    "document_url" TEXT NOT NULL,
    "company" TEXT,
    "promoter" REAL,
    "fii" REAL,
    "dii" REAL,
    "public" REAL,
    "shareholders" INTEGER,
    "shares" REAL,
    "holders" TEXT NOT NULL,
    "parser_version" INTEGER NOT NULL,
    "parsed_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("market", "symbol", "period_end")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "transcript_documents" (
    "id" TEXT NOT NULL,
    "sha256" TEXT NOT NULL,
    "size_bytes" INTEGER NOT NULL,
    "extraction_method" TEXT NOT NULL,
    "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("id")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "transcript_outlooks" (
    "id" TEXT NOT NULL,
    "transcript_id" TEXT NOT NULL,
    "market" TEXT NOT NULL DEFAULT 'NSE',
    "symbol" TEXT NOT NULL,
    "call_date" TEXT,
    "model_name" TEXT NOT NULL,
    "analysis_version" TEXT NOT NULL,
    "outlook_score" REAL NOT NULL,
    "verified_fields" INTEGER NOT NULL DEFAULT 0,
    "unverified_fields" INTEGER NOT NULL DEFAULT 0,
    "extraction" TEXT NOT NULL,
    "prompt_tokens" INTEGER NOT NULL DEFAULT 0,
    "completion_tokens" INTEGER NOT NULL DEFAULT 0,
    "cost_usd" REAL NOT NULL DEFAULT 0,
    "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("id")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "transcript_sentiments" (
    "id" TEXT NOT NULL,
    "transcript_id" TEXT NOT NULL,
    "overall_score" REAL NOT NULL,
    "optimism_score" REAL NOT NULL,
    "guidance_score" REAL NOT NULL,
    "risk_score" REAL NOT NULL,
    "confidence_score" REAL NOT NULL,
    "analyst_pressure" REAL NOT NULL,
    "management_confidence" REAL NOT NULL,
    "answer_quality" REAL NOT NULL,
    "guidance_direction" TEXT NOT NULL,
    "structured_output" TEXT NOT NULL,
    "model_name" TEXT NOT NULL,
    "analysis_version" TEXT NOT NULL,
    "estimated_cost_usd" REAL NOT NULL DEFAULT 0,
    "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    PRIMARY KEY ("id")
) WITHOUT ROWID;

CREATE TABLE IF NOT EXISTS "transcripts" (
    "id" TEXT NOT NULL,
    "document_id" TEXT NOT NULL,
    "symbol" TEXT NOT NULL,
    "quarter" TEXT,
    "call_date" TEXT,
    "cleaned_text" TEXT NOT NULL,
    "token_count" INTEGER NOT NULL,
    "text_hash" TEXT NOT NULL,
    "created_at" TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
    "market" TEXT NOT NULL DEFAULT 'NSE',
    PRIMARY KEY ("id")
) WITHOUT ROWID;
